    def test_serve(self):
        response = self.fetch("/static/foo.txt")
        self.assertEqual(response.body, b("bar"))

    def test_static_url(self):
        response = self.fetch("/static_url/foo.txt")
        self.assertEqual(response.body, b("/static/foo.txt?v=42"))

